import json, re

def main(result: list) -> dict:
    criteria = {}
    for item in result:
        first = str(item.get("content", "")).split("\n", 1)[0]
        m = re.match(r"^\[NHÓM (\d{4})\] (.+?)(?: — Phân nhóm \d+)?(?: \| EN: (.+))?$", first)
        if m and m.group(1) not in criteria:
            criteria[m.group(1)] = m.group(2) + (f" / {m.group(3)}" if m.group(3) else "")
    criteria["KHONG_PHU_HOP"] = "Không nhóm nào trong danh sách bao trùm hàng hóa này"
    q = {"nhom": {"type": "choice",
        "instructions": "Chọn nhóm 4 số trong Biểu thuế XNK Việt Nam bao trùm đúng hàng hóa được mô tả, theo tên nhóm và chú giải (Quy tắc 1).",
        "criteria": criteria}}
    return {"questions": json.dumps(q, ensure_ascii=False)}

def main(answers: dict) -> dict:
    probs = sorted(answers["nhom"]["probabilities"].items(), key=lambda x: -x[1])
    chosen, total = [], 0.0
    for code, p in probs:
        total += p  # tính cả KHONG_PHU_HOP vào tổng, nhưng không chọn nó
        if code != "KHONG_PHU_HOP" and p >= 0.02:
            chosen.append(code)
        if len(chosen) >= 5 or total >= 0.95:
            break
    if not chosen:  # Jev nghiêng hẳn về KHONG_PHU_HOP -> vẫn thử 2 nhóm đầu, bước 2 tự từ chối nếu sai
        chosen = [c for c, _ in probs if c != "KHONG_PHU_HOP"][:2]
    return {"nhom": chosen}

import json

MAX_OPTS, KEEP_MASS, MIN_SUBS, MAX_SUBS = 254, 0.95, 2, 5


def main(all_paths: dict, sub_answers: dict) -> dict:
    """Chỉ xét mã 8 số thuộc các phân nhóm Jev đã chọn (Quy tắc 6), áp dụng cho MỌI nhóm."""
    prob = sub_answers["phan_nhom"]["probabilities"]
    keep, total = [], 0.0
    every = {c[:6] for c in all_paths} | {"KHONG_PHU_HOP"}
    for s, p in sorted(((s, prob.get(s, 0.0)) for s in every), key=lambda x: -x[1]):
        if len(keep) >= MIN_SUBS and (total >= KEEP_MASS or len(keep) >= MAX_SUBS):
            break
        total += p
        if s != "KHONG_PHU_HOP":
            keep.append(s)
    opts = {c: v for c, v in all_paths.items() if c[:6] in keep}
    if len(opts) > MAX_OPTS:  # vượt giới hạn Jev -> bỏ phân nhóm xác suất thấp nhất trước
        opts = dict(sorted(opts.items(), key=lambda kv: -prob.get(kv[0][:6], 0.0))[:MAX_OPTS])
    opts["KHONG_PHU_HOP"] = "Không mã nào mô tả đúng hàng hóa (thiếu thông tin hoặc sai nhóm)"
    q = {"ma": {"type": "choice",
        "instructions": "Chọn mã HS 8 số mô tả đúng nhất hàng hóa ở dòng 'Mô tả hàng hóa'. Các chú giải đi kèm là căn cứ bắt buộc (định nghĩa, loại trừ). Mỗi lựa chọn là đường dẫn từ nhóm tới dòng hàng; 'Loại khác (không phải: A, B)' nghĩa là hàng không thuộc A, B.",
        "criteria": opts}}
    return {"questions": json.dumps(q, ensure_ascii=False), "paths": opts}

import json

MAX_OPTS = 254


def main(trees: list, message: str) -> dict:
    """Đọc cây JSON (hs_tree/XXXX.json) của các nhóm đã chọn -> câu hỏi Jev chọn phân nhóm 6 số."""
    heads, notes, opts, subs = [], {}, {}, {}
    for raw in trees:
        t = json.loads(raw)
        g = f"Nhóm {t['code'][:2]}.{t['code'][2:]}"
        heads.append(f"{g}: {t['name']} ({t['chapter']})")
        for title, body in t["notes"].items():
            notes.setdefault(title, body)
        for s, path in t["subheadings"].items():
            subs[s] = f"{g} ({t['name']})" + (f" > {path}" if path else "")
        for c, v in t["codes"].items():
            opts[c] = f"{g} > {v['path']}" + (f" | Ghi chú: {v['note']}" if v["note"] else "")
    subs = dict(list(subs.items())[:MAX_OPTS])
    q = {"phan_nhom": {"type": "choice",
        "instructions": "Chọn phân nhóm 6 số mô tả đúng nhất hàng hóa ở dòng 'Mô tả hàng hóa' (Quy tắc 1 và 6). Các chú giải đi kèm là căn cứ bắt buộc (định nghĩa, loại trừ).",
        "criteria": {**subs, "KHONG_PHU_HOP": "Không phân nhóm nào mô tả đúng hàng hóa"}}}
    state = (f"Mô tả hàng hóa: {message}\n\n## Các nhóm đang xét\n" + "\n".join(heads) + "\n\n"
             + "\n\n".join(f"## {h}\n{b}" for h, b in notes.items()))
    return {"questions": json.dumps(q, ensure_ascii=False), "state": state, "all_paths": opts, "subs": subs}

